import re

PATTERNS = {
    "email": re.compile(r"[\w.+-]+@[\w-]+\.[\w.]+"),
    "us_ssn": re.compile(r"\b\d{3}-\d{2}-\d{4}\b"),
    "phone": re.compile(r"\+?\d[\d\s().-]{8,}\d"),
}

def redact(text: str) -> str:
    # A simple first pass. Real projects add a proper PII detector
    # and human review, since regex misses names and addresses.
    for label, pat in PATTERNS.items():
        text = pat.sub(f"[{label.upper()}]", text)
    return text

print(redact("Call Ann at +1 415 555 0100 or ann@example.com, SSN 123-45-6789"))

# Terraform: an S3 bucket encrypted with a customer-managed KMS key
resource "aws_kms_key" "claims" {
  description         = "Key for claims data"
  enable_key_rotation = true
}

resource "aws_s3_bucket" "claims" {
  bucket = "acme-claims-eu"          # created in the EU provider region
}

resource "aws_s3_bucket_server_side_encryption_configuration" "claims" {
  bucket = aws_s3_bucket.claims.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.claims.arn
    }
  }
}

-- A simple application audit table (append-only by convention and grants)
CREATE TABLE audit_log (
  id           BIGSERIAL PRIMARY KEY,
  at           TIMESTAMPTZ NOT NULL DEFAULT now(),
  actor        TEXT NOT NULL,          -- user id or service account
  action       TEXT NOT NULL,          -- 'read', 'export', 'delete'
  resource     TEXT NOT NULL,          -- 'patients/8812'
  source_ip    INET,
  request_id   TEXT                    -- ties to logs and traces
);

-- The app may insert, but nobody gets UPDATE or DELETE on it
REVOKE UPDATE, DELETE ON audit_log FROM app_role;
GRANT INSERT, SELECT ON audit_log TO app_role;

import logging, json, uuid, time

class JsonFormatter(logging.Formatter):
    def format(self, record):
        base = {"ts": time.strftime("%Y-%m-%dT%H:%M:%S"),
                "level": record.levelname, "msg": record.getMessage()}
        base.update(getattr(record, "fields", {}))   # extra named fields
        return json.dumps(base)

handler = logging.StreamHandler()
handler.setFormatter(JsonFormatter())
log = logging.getLogger("claims"); log.addHandler(handler); log.setLevel("INFO")

