from fastapi import FastAPI
app = FastAPI()

@app.get("/claims/{cid}")                 # sync: fast lookup
def get_claim(cid: int):
    return db.get_claim(cid)

@app.post("/claims/{cid}/fraud-report", status_code=202)   # async
def request_report(cid: int):
    job = jobs.create(kind="fraud_report", claim_id=cid, status="queued")
    queue.send({"job_id": job.id})         # hand off to workers
    return {"job_id": job.id, "status_url": f"/jobs/{job.id}"}

@app.get("/jobs/{job_id}")                 # client polls this
def job_status(job_id: str):
    j = jobs.get(job_id)
    return {"status": j.status, "result": j.result}

from anthropic import Anthropic
from celery.schedules import crontab

client = Anthropic()

@app.task
def nightly_coding_batch():
    docs = db.summaries_since_yesterday()
    batch = client.messages.batches.create(requests=[
        {"custom_id": f"doc-{d.id}",                # match results later
         "params": {"model": MODEL, "max_tokens": 300,
                    "messages": [{"role": "user", "content": PROMPT + d.text}]}}
        for d in docs])
    db.save_batch(batch.id)                         # poll it in another task

app.conf.beat_schedule = {                         # Celery beat only enqueues
    "nightly-coding": {"task": "tasks.nightly_coding_batch",
                       "schedule": crontab(hour=1, minute=0)},
}
